  order?: number;
  period?: number;
  forward?: number;
  backward?: number;
  intercept?: number;
  displayRSq?: boolean;
  displayEq?: boolean;
  color?: string;
  /** Trendline width in points (`c:trendline/c:spPr/a:ln/@w`, EMU / 12700). */
  lineWidth?: number;
