  cropLeft?: number;
  /** Crop from top edge as 0..1 fraction (OOXML `a:srcRect/@t`). */
  cropTop?: number;
  /** Crop from right edge as 0..1 fraction (OOXML `a:srcRect/@r`). */
  cropRight?: number;
  /** Crop from bottom edge as 0..1 fraction (OOXML `a:srcRect/@b`). */
  cropBottom?: number;
