  fillRectTop?: number;
  /** Stretch target inset from the right frame edge (`a:fillRect/@r`). */
  fillRectRight?: number;
  /** Stretch target inset from the bottom frame edge (`a:fillRect/@b`). */
  fillRectBottom?: number;
