  /** Motion-path rotation centre X in slide percentage units (`p:rCtr/@x`). */
  motionPathRotationCenterX?: number;
  /** Motion-path rotation centre Y in slide percentage units (`p:rCtr/@y`). */
  motionPathRotationCenterY?: number;
